// Placeholder Firebase options for CI.
//
// The real lib/firebase_options.dart is generated by `flutterfire configure`
// and git-ignored. CI copies this file into its place so the app can be
// analyzed and unit-tested without any project's settings. Nothing here
// reaches a real Firebase project; release builds use the real file, which
// the release workflow restores from the FIREBASE_OPTIONS_DART_BASE64 secret.
import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart'
    show defaultTargetPlatform, kIsWeb, TargetPlatform;

class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform {
    if (kIsWeb) {
      throw UnsupportedError('Web is not configured.');
    }
    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;
      case TargetPlatform.iOS:
        return ios;
      default:
        throw UnsupportedError('This platform is not configured.');
    }
  }

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'ci-placeholder',
    appId: '1:000000000000:android:0000000000000000',
    messagingSenderId: '000000000000',
    projectId: 'demo-accounts-note',
    storageBucket: 'demo-accounts-note.appspot.com',
  );

  static const FirebaseOptions ios = FirebaseOptions(
    apiKey: 'ci-placeholder',
    appId: '1:000000000000:ios:0000000000000000',
    messagingSenderId: '000000000000',
    projectId: 'demo-accounts-note',
    storageBucket: 'demo-accounts-note.appspot.com',
    iosBundleId: 'com.accountsnote.app',
  );
}
